<script setup>
import { computed } from 'vue';
import {reference,dateOf} from './domain.js';
const props=defineProps({records:Array,profile:Object,type:String});
const chart=computed(()=>{const items=[...props.records].sort((a,b)=>a.day.localeCompare(b.day));if(!items.length)return null;const values=items.flatMap(r=>{const ref=reference(props.profile.sex,props.profile.birth,r.day,props.type,r[props.type]);return [r[props.type],...(ref?ref.range:[])];});const min=Math.floor(Math.min(...values)*.9),max=Math.max(...values)*1.08,span=max-min||1;const start=dateOf(items[0].day).getTime(),end=dateOf(items.at(-1).day).getTime();const x=r=>end===start?250:48+(dateOf(r.day)-start)/(end-start)*414;const y=v=>180-(v-min)/span*140;const points=items.map(r=>({id:r.id,x:x(r),y:y(r[props.type]),value:r[props.type],day:r.day}));const band=items.map(r=>{const ref=reference(props.profile.sex,props.profile.birth,r.day,props.type,r[props.type]);return ref?{x:x(r),low:y(ref.range[0]),high:y(ref.range[1])}:null;}).filter(Boolean);return {points,line:points.map(p=>`${p.x},${p.y}`).join(' '),band:[...band.map(p=>`${p.x},${p.high}`),...band.slice().reverse().map(p=>`${p.x},${p.low}`)].join(' '),ticks:[0,1,2,3].map(i=>({y:40+i*140/3,label:(max-i*span/3).toFixed(1)}))};});
</script>
<template><div v-if="chart" class="growth-chart"><svg viewBox="0 0 500 225" role="img" :aria-label="type==='weight'?'体重变化曲线，单位千克':'身高变化曲线，单位厘米'"><g v-for="t in chart.ticks" :key="t.y"><line x1="44" :y1="t.y" x2="470" :y2="t.y" stroke="#e9e7df" stroke-dasharray="4 5"/><text x="4" :y="t.y+4">{{t.label}}</text></g><polygon :points="chart.band" fill="#e6ead9" opacity=".75"/><polyline :points="chart.line" fill="none" stroke="#a9b982" stroke-width="3" stroke-linejoin="round"/><circle v-for="p in chart.points" :key="p.id" :cx="p.x" :cy="p.y" r="4.5" fill="#84985c" stroke="white" stroke-width="2"><title>{{p.day}}：{{p.value}}</title></circle><text x="44" y="210">{{chart.points[0].day.slice(5)}}</text><text x="430" y="210">{{chart.points.at(-1).day.slice(5)}}</text></svg><p class="chart-legend"><i></i>宝宝的记录 <i class="range"></i>同月龄 P3–P97 参考区间</p></div><p v-else class="empty">记录第一次测量，开始绘制成长曲线。</p></template>
